xfs_buf_t*
xfs_buf_find(struct xfs_buftarg	*btp,
		struct xfs_buf_map	*map,
		int			nmaps,
		xfs_buf_flags_t		flags,
		xfs_buf_t		*new_bp)
{
	xfs_buf_t		*bp = NULL;
	uint64_t		total_bytes = 0;
	int			i;

	for (i = 0; i < nmaps; i++) {
		total_bytes += (uint64_t)map[i].bm_len << btp->bt_blocklog;
	}

	bp = xfs_buf_find_noalign(btp, map, nmaps, flags, new_bp);

	if (!bp)
		return NULL;

	if ((flags & XBF_STALE_OK) && xfs_buf_isstale(bp)) {
		xfs_buf_unlock(bp);
		xfs_buf_rele(bp);
		return NULL;
	}

	if (flags & XBF_LOCK) {
		if (!xfs_buf_lock(bp)) {
			xfs_buf_rele(bp);
			return NULL;
		}
	}

	if (!bp->b_bn) {
		xfs_buf_rele(bp);
		return NULL;
	}

	return bp;
}

xfs_buf_t *
xfs_buf_search(struct xfs_buftarg *btp, struct xfs_buf_map *map, int nmaps,
		xfs_buf_flags_t flags, xfs_buf_t *new_bp)
{
	xfs_buf_t	*bp;
	xfs_daddr_t	blkno;
	uint		numblks;
	uint		i;
	int		error;

	blkno = 0;
	numblks = 0;
	for (i = 0; i < nmaps; i++) {
		blkno += map[i].bm_bn;
		numblks += map[i].bm_len;
	}

	bp = xfs_buf_find(btp, blkno, numblks, flags, &error);
	if (bp) {
		if (bp->b_stale) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			return NULL;
		}
		if (xfs_buf_lock(bp)) {
			if (bp->b_flags & XBF_STALE) {
				xfs_buf_stale(bp);
				xfs_buf_relse(bp);
				return NULL;
			}
			return bp;
		}
		return bp;
	}

	if (new_bp) {
		new_bp->b_bn = blkno;
		new_bp->b_bno = blkno;
		new_bp->b_flags = flags;
		new_bp->b_bcount = numblks;
		new_bp->b_bufobj = &btp->bt_bufobj;
		new_bp->b_target = btp;
		xfs_buf_hold(new_bp);
		xfs_buf_insert(new_bp);
		return new_bp;
	}

	return NULL;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_off_t		blkno = 0;
	xfs_off_t		count = 0;
	xfs_buf_t		*bp;
	int			i;

	for (i = 0; i < nmaps; i++) {
		blkno += map[i].bm_offset;
		count += map[i].bm_length;
	}

	bp = xfs_buf_find_noalign(btp, blkno, count, flags);
	if (bp) {
		if ((flags & XBF_TRYLOCK) && !xfs_buf_lock(bp)) {
			xfs_buf_relse(bp);
			bp = NULL;
		}
		if (bp && xfs_buf_stale(bp)) {
			xfs_buf_relse(bp);
			bp = NULL;
		}
	}

	if (!bp && new_bp) {
		new_bp->b_bn = blkno;
		new_bp->b_count = count;
		xfs_buf_lock(new_bp);
		xfs_buf_insert(new_bp, btp);
		bp = new_bp;
	}

	return bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	xfs_off_t		total_bytes = 0;
	xfs_buf_t		*bp = NULL;
	int			i;

	for (i = 0; i < nmaps; i++) {
		total_bytes += map[i].bm_len << btp->bt_sshift;
	}

	if (total_bytes == 0)
		return NULL;

	bp = xfs_buf_find_ag(btp, map[0].bm_offset, total_bytes,
			flags, NULL);

	if (bp) {
		if (bp->b_flags & XBF_STALE) {
			xfs_buf_stale(bp);
			xfs_buf_relse(bp);
			bp = NULL;
		} else {
			if (xfs_buf_lock(bp))
				return NULL;
		}
	}

	if (!bp && new_bp) {
		new_bp->b_maps = map;
		new_bp->b_nmapped = nmaps;
		new_bp->b_flags = flags;
		xfs_buf_insert(new_bp);
		bp = new_bp;
	}

	return bp;
}

xfs_buf_t*
xfs_buf_find(
	struct xfs_buftarg	*btp,
	struct xfs_buf_map	*map,
	int			nmaps,
	xfs_buf_flags_t		flags,
	xfs_buf_t		*new_bp)
{
	struct xfs_buf		*bp;
	int64_t		total_bytes = 0;
	int		i;

	for (i = 0; i < nmaps; i++) {
		total_bytes += XFS_BUF_MAP_SIZE(map[i]);
	}

	bp = xfs_buf_find_common(btp, map, nmaps, flags);

	if (bp) {
		if ((flags & XBF_TRYLOCK) && !xfs_buf_lock(bp)) {
			xfs_buf_relse(bp);
			return NULL;
		}
		return bp;
	}

	if (new_bp) {
		new_bp->b_maps = map;
		new_bp->b_nmapped = nmaps;
		new_bp->b_buftarg = btp;
		xfs_buf_insert(new_bp);
		return new_bp;
	}

	return NULL;
}
